fn main() {
    // ---- Lifetime elision: Rust infers lifetimes ----

    // ---- Example 1: Single input ----
    // No lifetime annotation needed
    let s = String::from("hello");
    let word = first_word(&s);  // &str is inferred
    println!("First word: {}", word);

    // ---- Example 2: &self ----
    // No lifetime annotation needed
    let text = String::from("Hello, world!");
    let excerpt = ImportantExcerpt { part: &text };
    println!("Excerpt: {}", excerpt.part);

    // ---- Example 3: Multiple inputs, one output ----
    // Needs explicit lifetimes
    let s1 = String::from("abcd");
    let s2 = "xyz";
    let result = longest(s1.as_str(), s2);
    println!("Longest: {}", result);
}

// ---- Elision Rule 1: Single input lifetime ----
// &str is actually &'a str (implicit)
fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[0..i];
        }
    }
    &s[..]
}

// ---- Elision Rule 2: &self ----
// &self's lifetime is used for the return
struct ImportantExcerpt<'a> {
    part: &'a str,
}

impl<'a> ImportantExcerpt<'a> {
    // &self's lifetime is 'a, so the return is 'a
    fn announce_and_return_part(&self, announcement: &str) -> &str {
        println!("Announcement: {}", announcement);
        self.part
    }
}

// ---- Elision Rule 3: Multiple inputs ----
// Needs explicit lifetimes
fn longest<'a>(s1: &'a str, s2: &'a str) -> &'a str {
    if s1.len() > s2.len() {
        s1
    } else {
        s2
    }
}

// ---- When lifetimes are required ----
// 1. Multiple input lifetimes, one output
// 2. Multiple output lifetimes
// 3. Struct with references

// ---- When lifetimes are elided ----
// 1. Single input lifetime
// 2. &self or &mut self
// 3. No outputs

// ---- Explicit vs Elided ----
// Explicit: fn longest<'a>(x: &'a str, y: &'a str) -> &'a str
// Elided:  fn first_word(s: &str) -> &str

// ---- Lifetimes are always there ----
// Even when elided, the compiler still uses them
// It just figures them out for you

